mapper.select:


    and c.country = #{country}
    and c.degree = #{degree}
    and c.result = #{result}
    and c.verify_level = #{verifyLevel}
    and c.season = #{season}
    and (c.school_name like concat('%', #{schoolName}, '%') or c.program_name like concat('%', #{schoolName}, '%'))
    and c.lead_id = #{leadId}
    and c.publicity_consent = 'Y'

order by c.season desc, c.case_id desc


where c.result = 'admit' and c.verify_level in ('A', 'B') and c.publicity_consent = 'Y' and c.revoke_time is null and c.status = '0'
and c.country = #{country}
and c.degree = #{degree}
order by c.season desc, c.case_id desc

select count(*) from abr_case
where lead_id = #{leadId} and program_id = #{programId} and season = #{season}
and case_id <> #{caseId}
